// Make sure the page isn't empty - this was reported as a problem when
// the system times you out
if (!myStepPage.isEmpty()) 
{
	// Unlock the work object's pxLockHandle
	String strLockHandle = myStepPage.getString(".pxLockHandle");
	if (strLockHandle.length() > 0)
	{
	   try { 
	      tools.getDatabase().getLockManager().unlock(strLockHandle, false);
	   } catch (DatabaseException e) {
	      oLog.error(e.getMessage());
	      tools.putParamValue("SuccessIndicator", "-6");
	      tools.putParamValue("FailureInfo", e.getMessage());											
	   }
	}
}
myStepPage.removeFromClipboard();

// rename page to param.workPage
// since this page is already the right work object,
// WorkLock will only reopen it if it is stale.
myStepPage.rename(tools.getParamValue("workPage"));

String flowSubscript = tools.getPrimaryPage().getString(".pxFlowName");
if (flowSubscript.equals(""))
{
	tools.putParamValue("SuccessIndicator", "-26");
	tools.putParamValue("FailureInfo", tools.getRuleMessage("\t[@baseclass.pyMessageLabel]ProblemAssignment_FlowNameMissing"));
	tools.putParamValue("FailureMsgDesc", "ProblemAssignment_FlowNameMissing");
}
else
{
	ClipboardProperty flowRef = myStepPage.getIfPresent(".pxFlow(" + flowSubscript + ")");
	if (flowRef != null)
	{
		ClipboardPage flowPage = flowRef.getPageValue();
		String assignHandle = flowPage.getString(".pxAssignmentKey");
		String assignTask = tools.getPrimaryPage().getString(".pxTaskName");

		// First check if this is an internal assignment on only a stubbed out page.  If it is, and it is virtual, recreate it, otherwise open it
		if (assignHandle.startsWith("ASSIGN-INTERNAL") && assignTask.equals(""))
		{
			ClipboardPage assignPage;
			if (flowPage.getBoolean("pxAssignIsVirtual"))
				assignPage = pega_procom_pegaprocomutilities.pxCreateAssignmentFromFlowPage(flowPage, tools.getPrimaryPage().getName());
			else
			{
				try {
					assignPage = tools.getDatabase().open(assignHandle, false);
                  	// BUG-277915 The page is retrieved from DB but its still name less and in populateFlowActions we use this page name.
                  	assignPage.rename(tools.getParamValue("assignPage"));
                    if(assignPage.getIfPresent("pyFlowType") == null){
                  	   assignPage.putString("pyFlowType", flowPage.getString(".pyFlowType"));
                    }
				} catch (DatabaseException de) { 
					tools.getStepStatus().backoutWorst(); 
					// It should have opened, but we can move on anyway
					assignPage = pega_procom_pegaprocomutilities.pxCreateAssignmentFromFlowPage(flowPage, tools.getPrimaryPage().getName());
				}
			}
			pega_procom_pegaprocomutilities.populateFlowActions(assignPage, myStepPage, tools);
			return true;
		}

		// Now we must check to see if the flow is still at this assignment task

		String flowTask = flowPage.getString(".pyLastFlowStep");
		if (!assignTask.equals(flowTask))
		{
			tools.putParamValue("SuccessIndicator", "-21");
			tools.putParamValue("FailureInfo", tools.getRuleMessage("OpenAndLockWork-FlowNotAtTask"));
			tools.putParamValue("FailureMsgDesc", "ProblemAssignment_FlowNotAtTask");
		}
		else
		{
			// Alright, the assignment's flow still exists, and it is at the right task.
			// The only thing left to do is compare the handles.  They could be out of synch
			// if GetNextWork just transferred a workbasket assignment to a worklist
			String thisHandle = null;
			try { thisHandle = tools.getDatabase().getHandle(tools.getPrimaryPage()); }
			catch (DatabaseException e) { thisHandle = null; }
			if (thisHandle == null || !assignHandle.equals(thisHandle))
			{
				tools.putParamValue("SuccessIndicator", "-23");
				tools.putParamValue("FailureInfo", tools.getRuleMessage("OpenAndLockWork-AssignMismatch"));
				tools.putParamValue("FailureMsgDesc", "ProblemAssignment_AssignMismatch");
			}
			else if (tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "skipFlowActionPopulate") == false)
			{
				// Let's go ahead and populate the flow actions for this assignment
				// If the Rule-Obj-Flow is gone, populateFlowActions will add a message to the pyFlowType property
				// If just the particular assignment that we're populating is gone, flow processing will add a
				// message to the pyLastFlowStep property.
				pega_procom_pegaprocomutilities.populateFlowActions(tools.getPrimaryPage(), myStepPage, tools);
				if (flowPage.getMessages("pyFlowType").length() > 0)
				{
					tools.putParamValue("SuccessIndicator", "-24");
					tools.putParamValue("FailureInfo", flowPage.getMessages("pyFlowType"));
				}
				else if (flowPage.getMessages("pyLastFlowStep").length() > 0)
				{
					tools.putParamValue("SuccessIndicator", "-25");
					tools.putParamValue("FailureInfo", flowPage.getMessages("pyLastFlowStep"));
				}
			}
			else
			{
				// skipFlowActionPopulate is true, so make sure the assign actions are cleared out
				tools.getPrimaryPage().getProperty(".pyAssignActions").removeFromClipboard();
			}

			// Let's copy some values over from the assignment to the pxFlow page to keep them up to date, in case
			// they changed on the assignment but pxFlow wasn't updated as well.
			flowPage.putString(".pxAssignGoalTime", tools.getPrimaryPage().getString(".pxGoalTime"));
			flowPage.putString(".pxAssignDeadTime", tools.getPrimaryPage().getString(".pxDeadlineTime"));
			flowPage.putString(".pxAssignStatus", tools.getPrimaryPage().getString(".pyAssignmentStatus"));
		}
	}
	else
	{
		tools.putParamValue("SuccessIndicator", "-22");
		tools.putParamValue("FailureInfo", tools.getRuleMessage("OpenAndLockWork-FlowRemoved"));
		tools.putParamValue("FailureMsgDesc", "ProblemAssignment_FlowRemoved");
	}
	int nSuccessIndicator = tools.getParamAsInteger(PropertyInfo.TYPE_INTEGER, "SuccessIndicator");
	switch (nSuccessIndicator) {
		case -21:
		case -22:
		case -23:
			try { 
				String strAssignHandle = tools.getDatabase().getHandle(tools.getPrimaryPage());
				if (strAssignHandle != null) {
					ClipboardPage assignmentPage = tools.getDatabase().open(strAssignHandle, false);
					if (assignmentPage == null || !assignmentPage.getString(".pxTaskName").equals(tools.getPrimaryPage().getString(".pxTaskName"))) {
						// Assignment is gone; re-set SuccessIndicator to -28
						tools.putParamValue("SuccessIndicator", -28);
						tools.putParamValue("FailureInfo", tools.getRuleMessage("OpenAndLockWork-AssignNotAvailable"));
						tools.putParamValue("FailureMsgDesc", "ProblemAssignment_AssignNotAvailable");
					}
				}
			} catch (DatabaseException de) {
				String errorMessage = de.getMessage();
				String stackTrace = pega_rules_utilities.getStackTrace(de);
				String status = pega_procom_processenginestatus.statusFailAssignInvalidHandle();
				oLog.error(de);
				tools.getStepStatus().set(ProcessingStatus.SEVERITY_FAIL, errorMessage, "");
			}

			break;
		default:
			break;
	}
}
